/* Types */
/**  Commands the workbench runs, whatever editor is open. */
export type AppCommandId = "file.newProject" | "file.copyProject" | "file.importXLights" | "file.newSequence" | "file.openProject" | "file.save" | "file.reloadFromDisk" | "file.closeEditor" | "file.closeWindow" | "file.settings" | "edit.undo" | "edit.redo" | "view.toggleGuiMode" | "view.toggleSpectrogram" | "view.toggleMarksLaneOnly" | "view.openLayerGraph" | "view.toggleProjectTree" | "view.focusExplorer" | "view.focusSearch" | "view.focusProblems" | "workbench.quickOpen" | "workbench.commandPalette" | "project.reload" | "perform.stop";

export type AppSettings = {
	reopenLastProject: boolean,
	editorViewMode?: EditorViewMode,
	reopenPreviewWindow: boolean,
	autosaveProjectEdits: boolean,
	sequenceInitialZoomMode: SequenceInitialZoomMode,
	sequenceFollowMode: SequenceFollowMode,
	/**  Timeline drags snap to marks and clip edges; holding Alt inverts this for the gesture. */
	sequenceSnap: boolean,
	sequenceClipMatch: SequenceClipMatch,
	sequenceInitialPxPerSecond: number,
	sequenceInitialLaneHeightPx: number,
	sequenceSpectrogramEnabled?: boolean,
	sequenceSpectrogramTimeResolutionMs?: number,
	sequenceSpectrogramFftSize?: number,
	/**  Marks draw only in the Marks lane instead of also across the waveform and lanes. */
	sequenceMarksLaneOnly?: boolean,
	clipRaster: ClipRasterSettings,
	spatialSnap: SpatialSnapSettings,
	/**  Commands whose keys differ from their defaults. */
	keybindings?: KeyBinding[],
};

export type AppSnapshot = {
	stateRevision: number,
	projectEpoch: number,
	settings: AppSettings,
	workspaceLayout: WorkspaceLayoutState,
	workspaceExplorer: WorkspaceExplorerState,
	projectRoot: string | null,
	projectHealth: ProjectHealth,
	projectRevision: number,
	projectEntries: WorkspaceEntry[],
	tabs: EditorTab[],
	pendingSaves: DocumentSaveStatus[],
	activeFile: string | null,
	activeBuffer: EditorTab | null,
	activeDocumentDescriptor: DocumentDescriptor | null,
	diagnostics: IoDiagnostic[],
	status: string,
	renderError: string | null,
	previewError: string | null,
	previewOpen: boolean,
	audioTransport: AudioTransportSnapshot,
	liveOutput: LiveOutputSnapshot,
	devices: DonderDeviceStatus[],
};

export type AudioTransportSnapshot = {
	state: AudioTransportState,
	audio: SequenceAudio | null,
	generation: number,
	positionSeconds: number,
	startDelaySeconds: number,
	homeSeconds: number,
	durationSeconds: number,
	playbackSpeed: PlaybackSpeed,
	range: PlaybackRange | null,
	looping: boolean,
	lastError: string | null,
};

export type AudioTransportState = "unloaded" | "playing" | "paused" | "stopped" | "ended" | "error";

export type BufferExternalState = "current" | "changedOnDisk" | "deletedOnDisk";

export type ClipRasterSettings = {
	maxColumns: number,
	maxRows: number,
	minFrameStride: number,
};

export type CommandId = AppCommandId | EditorCommandId;

/**  Edits to the layers and composition graph that sequences and consoles share. */
